#!/usr/bin/env python3
"""Regenerates Sources/PersonalHub/Design/VendorMarks.swift from Token Monitor's assets/icons (MIT).

Usage: scripts/vendor-marks.py <token-monitor>/assets/icons
"""
import pathlib, re, sys

src = pathlib.Path(sys.argv[1])
out = pathlib.Path(__file__).resolve().parent.parent / "Sources/PersonalHub/Design/VendorMarks.swift"
lines = [
    "// Generated by scripts/vendor-marks.py. Do not edit.",
    "// Vendor marks from Token Monitor's assets/icons, MIT License, © 2026 Javis.",
    "",
    "enum VendorMarks {",
    "    /// Single-colour marks drawn with `currentColor`, tinted with the vendor colour.",
    "    static let mono: Set<String> = [MONO]",
    "",
    "    static let svg: [String: String] = [",
]
mono = []
for f in sorted(src.glob("*.svg")):
    text = re.sub(r"\s+", " ", f.read_text().strip())
    text = re.sub(r"<title>.*?</title>", "", text)
    colours = set(re.findall(r'(?:fill|stroke|stop-color)="(#[0-9a-fA-F]{3,8}|url\([^)]*\))"', text))
    if "currentColor" in text and not colours:
        mono.append(f.stem)
        assert '"##' not in text, f.name
    lines.append(f'        "{f.stem}": ##"{text}"##,')
lines.append("    ]")
lines.append("}")
body = "\n".join(lines).replace("MONO", ", ".join(f'"{m}"' for m in mono)) + "\n"
out.write_text(body)
print(f"{out}: {len(lines) - 9} marks, {len(mono)} mono")
